import loggingfrom functools import wrapsfrom typing import Any, Callable, Dict, Optionaldef log(filename: Optional[str] = None) -> Callable[[Callable[..., Any]], Callable[..., Any]]:    """    Декоратор для логирования начала и конца выполнения функции, а также её результатов или возникших ошибок.    Если filename задан, логи записываются в указанный файл.    Если filename не задан, логи выводятся в консоль.    """    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:        @wraps(func)        def wrapper(*args: Any, **kwargs: Dict[Any, Any]) -> Any:            # Начало выполнения функции            print(f"Начало выполнения функции {func.__name__}")            try:                # Результат функции может быть любого типа                result: Any = func(*args, **kwargs)                if filename:                    logging.basicConfig(filename=filename, level=logging.INFO)                    logger = logging.getLogger()                    logger.info(f"{func.__name__} ok")                    return result                else:                    print(f"{func.__name__} ok")                    return result            except Exception as e:                # Логирование аргументов функции                logger = logging.getLogger()                logger.error(f"{func.__name__} завершилась с ошибкой: {e}")                logger.exception(e)                # Запись информации об ошибке                if filename:                    logging.basicConfig(filename=filename, level=logging.ERROR)                    logger = logging.getLogger()                    logger.error("Входные параметры функции:")                    for arg in args:                        logger.error(arg)                    for key, value in kwargs.items():                        logger.error("%s: %s", key, value)                else:                    print(f"{func.__name__} завершилась с ошибкой: {e}")                raise e            finally:                # Конец выполнения функции                print(f"Конец выполнения функции {func.__name__}\n")        return wrapper    return decorator@log()  # Логирование в консольdef my_function(arg1: int, arg2: int) -> float:    if arg2 == 0:        print("Ошибка: деление на ноль")        raise ZeroDivisionError    else:        print("my_function выполнена")        return arg1 / arg2# # пример использования# @log() # filename="log.txt")# def my_function(x, y):#     return x + y## my_function(1, 2)# def checking_that_arg_is(predicate, error_message):#     def wrapper(function):#         def inner(arg):#             if not predicate(arg):#                 raise ValueError(error_message)#             return function(arg)#         return inner#     return wrapper### def predicate_is_int(x):#     return type(x) == int## def predicate_is_positive(x):#     return x > 0### @checking_that_arg_is(predicate_is_int, 'Значение должно быть целым числом')# @checking_that_arg_is(predicate_is_positive, 'Число должно быть положительным')# def square(x):#     return x * x### if __name__ == '__main__':#     # print(square(3))#     # print(square('3'))#     print(square(-3))### from time import time## def printing(func):##     def wrapper(*args, **kwargs):#         print(f'function {func} started')#         result = func(*args, **kwargs)#         print(f'function {func} finished')#         return result##     return wrapper### def timer(func):##     def wrapper(*args, **kwargs):#         print(f'timer started')#         time_1 = time()#         result = func(*args, **kwargs)#         time_2 = time()#         print(f'Time for work: {time_2 - time_1}')#         return result##     return wrapper### @timer# @printing# def example():#     for i in range(10000000):#         continue### example()#